<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\CompanyContent;use Illuminate\Http\{Request,RedirectResponse};use Illuminate\Validation\Rule;use Illuminate\View\View;
class CompanyContentController extends Controller{private const TYPES=['team','partner','statistic','value','licence','advantage','private_step','visa_step'];
 public function index(Request $r):View{abort_unless($r->user()->can('list-company-content'),403);$items=CompanyContent::with('translations')->when($r->filled('q'),fn($q)=>$q->whereTranslationLike('title','%'.$r->q.'%'))->when($r->filled('type'),fn($q)=>$q->where('type',$r->type))->when($r->filled('status'),fn($q)=>$q->where('is_active',$r->boolean('status')))->orderBy('type')->orderBy('sort_order')->paginate(20)->withQueryString();return view('admin.company_content.index',['items'=>$items,'types'=>self::TYPES]);}
 public function create(Request $r):View{abort_unless($r->user()->can('create-company-content'),403);return view('admin.company_content.form',['item'=>new CompanyContent,'types'=>self::TYPES]);}
 public function store(Request $r):RedirectResponse{abort_unless($r->user()->can('create-company-content'),403);CompanyContent::create($this->data($r));return redirect()->route('company-content.index')->with('message','Created.');}
 public function edit(Request $r,CompanyContent $company_content):View{abort_unless($r->user()->can('edit-company-content'),403);return view('admin.company_content.form',['item'=>$company_content,'types'=>self::TYPES]);}
 public function update(Request $r,CompanyContent $company_content):RedirectResponse{abort_unless($r->user()->can('edit-company-content'),403);$company_content->update($this->data($r));return back()->with('message','Updated.');}
 public function destroy(Request $r,CompanyContent $company_content):RedirectResponse{abort_unless($r->user()->can('delete-company-content'),403);$company_content->delete();return back()->with('message','Deleted.');}
 private function data(Request $r):array{$d=$r->validate(['type'=>['required',Rule::in(self::TYPES)],'image'=>['nullable','string','max:500'],'url'=>['nullable','string','max:500'],'value'=>['nullable','string','max:255'],'is_active'=>['nullable','boolean'],'sort_order'=>['nullable','integer','min:0'],'en.title'=>['required','string','max:255'],'en.subtitle'=>['nullable','string','max:255'],'en.description'=>['nullable','string']]);$d['is_active']=$r->boolean('is_active');$d['sort_order']??=0;return $d;}}
